export function evalLeaf(p, pool, b, s, lb, kind, pos, cs, ce, cls, hi, lo) {
    // One admitted scalar leaf on the item at pos (content [cs, ce), which is
    // also where the item ends): 0 matched, a reason, or a negated code.
    switch (kind) {
        case K_ANY: case K_MAJOR:
            return 0;
        case K_INT:
            return leafInt(p, pool, b, s, lb, pos, cs, ce, cls, hi, lo);
        case K_FLOAT:
            return leafFloat(p, b, s, lb, pos);
        case K_SIMPLE:
            return leafSimple(p, b, lb, pos);
        case K_LIT:
            return leafLit(p, pool, b, s, lb, pos, ce);
        case K_LITSET:
            return leafLitset(p, pool, b, s, lb, pos, ce);
        case K_TEXT:
            return leafText(p, b, s, lb, pos, cs, ce);
        case K_BYTES:
            return leafBytes(p, pool, b, s, lb, pos, cs, ce);
        case K_UINTX:
            return leafUintx(p, pool, b, s, lb, pos, cls, hi, lo);
        default:
            return R_TYPE;
    }
}

export function evalScalars(p, pool, b, s, fb, w, nq, pos, cs, ce, cls, hi, lo, unit) {
    // Every admitted scalar leaf of the query list, in query order, on the item
    // at pos: 1 unit each, then its own work; sets MATCHED or the failure
    // reason (bits 8-15) in the entry's flags. 0 or a negated code.
    const lv = p[H_S_LEAVES];
    const fl0 = fb + w;
    for (let i = 0; i < nq; i++) {
        const f = s[fl0 + i];
        if ((f & F_ADMITTED) !== 0) {
            const l = s[fb + i];
            const lb = lv + (8 * l);
            const kind = p[lb] & 255;
            if (scalarKind(kind)) {
                // unit 0: schedule 2's one-leaf child (D045), no leaf unit
                if (!charge(s, unit, pos)) {
                    return -R_BUDGET;
                }
                const r = evalLeaf(p, pool, b, s, lb, kind, pos, cs, ce, cls, hi, lo);
                if (r < 0) {
                    return r;
                }
                if (r === 0) {
                    s[fl0 + i] = f | F_MATCHED;
                } else {
                    s[fl0 + i] = f | (r << 8);
                }
            }
        }
    }
    return 0;
}
